language "moriarty-sherlock-draft/1";
program P {
  fn double(n: UInt): UInt { n + n }
  fn increment(n: UInt): UInt { n + 1 }
  fn add(a: UInt, b: UInt): UInt { a + b }
  entry add(double(2), increment(3));
}

