language "moriarty-sherlock-draft/1";
program P {
  fn deep(n: UInt): UInt { if n == 0 { 0 } else { 1 + deep(n - 1) } }
  fn under(a: UInt, b: UInt): UInt { a - b }
  fn add(a: UInt, b: UInt): UInt { a + b }
  entry add(deep(100), under(0, 1));
}

